                grid[r][c] = 0
                free_cells.append((r, c))
            else:
                grid[r][c] = 1

    # Directions for the plus shape: center, up, down, left, right
    moves = [
        (0, 0),
        (-1, 0),
        (1, 0),
        (0, -1),
        (0, 1)
    ]

    def is_valid_placement(r, c):
        """Check if placing a plus shape with center at (r, c) is valid."""
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= n:
                return False
            if grid[nr][nc] == 1:
                return False
        return True

    def apply_placement(r, c):
        """Mark the cells covered by a plus shape at (r, c)."""
        for dr, dc in moves:
            grid[r + dr][c + dc] = 1

    def remove_placement(r, c):
        """Unmark the cells covered by a plus shape at (r, c)."""
        for dr, dc in moves:
            grid[r + dr][c + dc] = 0

    def backtrack(index):
        """
        Try to cover all free cells starting from free_cells[index].
        We process free cells in the order they were found.
        If free_cells[index] is already covered, we skip it and move to the next.
        Otherwise, we must cover it now.
        """
        if index == len(free_cells):
            return True

        r, c = free_cells[index]

        # If this cell is already covered by a previous placement, skip it
        if grid[r][c] == 1:
            return backtrack(index + 1)

        # Try all possible centers that would cover (r, c)
        # A cell (r, c) can be covered if it is the center, or one of the arms.
        # So the center could be:
        # 1. (r, c) itself
        # 2. (r+1, c) if (r, c) is the top arm
        # 3. (r-1, c) if (r, c) is the bottom arm
        # 4. (r, c+1) if (r, c) is the left arm
        # 5. (r, c-1) if (r, c) is the right arm

        potential_centers = [
            (r, c),
            (r + 1, c),
            (r - 1, c),
            (r, c + 1),
            (r, c - 1)
        ]

        for cr, cc in potential_centers:
            if is_valid_placement(cr, cc):
                apply_placement(cr, cc)
                if backtrack(index + 1):
                    return True
                remove_placement(cr, cc)

        return False

    if backtrack(0):
        print("YES")
    else:
