    grid = []
    idx = 1
    for _ in range(n):
        grid.append(list(data[idx]))
        idx += 1

    # Convert grid to a mutable state for tracking covered cells
    # We will modify grid in place: '.' means free, '#' means occupied or covered
    # We need to distinguish between originally occupied '#' and newly covered cells.
    # Strategy: Keep a separate set or modify a copy. Let's modify a copy of the grid.
    # Actually, we can just use the grid itself if we mark covered cells with a special char,
    # but the problem says '#' is occupied. Let's use a separate 2D array for 'covered' status.
    # 0: free, 1: occupied (original), 2: covered by piece.

    state = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == '#':
                state[r][c] = 1 # Occupied

    # Directions for the plus shape relative to center (dr, dc)
    # Center is (0,0), arms are (0,1), (0,-1), (1,0), (-1,0)
    offsets = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def get_first_free():
        for r in range(n):
            for c in range(n):
                if state[r][c] == 0:
                    return (r, c)
        return None

    def is_valid_placement(r, c):
        # Check if placing a plus at (r, c) is valid
        # 1. Must be within bounds
        # 2. All 5 cells must be free (state == 0)
        # Note: We don't care about original '#' here because we check state[r][c] == 0 first.
        # If state[r][c] is 1, it's occupied, so invalid.

        if not (0 <= r < n and 0 <= c < n):
            return False

        # Check center
        if state[r][c] != 0:
            return False

        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < n):
                return False
            if state[nr][nc] != 0:
                return False
        return True

    def place_piece(r, c):
        state[r][c] = 2
        for dr, dc in offsets:
            state[r+dr][c+dc] = 2

    def remove_piece(r, c):
        state[r][c] = 0
        for dr, dc in offsets:
            state[r+dr][c+dc] = 0

    def backtrack():
        pos = get_first_free()
        if pos is None:
            return True # All free cells covered

        r, c = pos

        # Try all 4 positions where the center of the plus could be to cover (r, c)
        # The center can be at (r, c), (r, c-1), (r, c+1), (r, c-1) -> wait.
        # If the plus covers (r, c), the center of the plus can be:
        # 1. (r, c) -> (r, c) is center
        # 2. (r, c-1) -> (r, c) is right arm
        # 3. (r, c+1) -> (r, c) is left arm
        # 4. (r-1, c) -> (r, c) is bottom arm
        # 5. (r+1, c) -> (r, c) is top arm
        # So there are 5 possible centers.

        candidates = [
            (r, c),      # Center at (r,c)
            (r, c-1),    # Center at (r, c-1), arm at (r, c)
            (r, c+1),    # Center at (r, c+1), arm at (r, c)
            (r-1, c),    # Center at (r-1, c), arm at (r, c)
            (r+1, c)     # Center at (r+1, c), arm at (r, c)
        ]

        for cr, cc in candidates:
            if is_valid_placement(cr, cc):
                place_piece(cr, cc)
                if backtrack():
                    return True
                remove_piece(cr, cc)

        return False

    if backtrack():
        print("YES")
    else:
        print("NO")

