    n = int(data[0])
    grid = []
    idx = 1
    for _ in range(n):
        grid.append(data[idx])
        idx += 1

    # Convert grid to a set of (r, c) tuples for free cells
    free_cells = set()
    for r in range(n):
        for c in range(n):
            if grid[r][c] == '.':
                free_cells.add((r, c))

    # If no free cells, it's trivially YES (0 pieces needed)
    if not free_cells:
        print("YES")
        return

    # Precompute all valid placements of the 'plus' piece
    # A placement is defined by its center (cr, cc) and covers (cr-1, cc), (cr+1, cc), (cr, cc-1), (cr, cc+1), (cr, cc)
    placements = []
    for r in range(n):
        for c in range(n):
            # Check if center is free
            if (r, c) not in free_cells:
                continue

            # Check neighbors
            cells = [(r, c)]
            if r > 0 and (r-1, c) in free_cells:
                cells.append((r-1, c))
            if r < n-1 and (r+1, c) in free_cells:
                cells.append((r+1, c))
            if c > 0 and (r, c-1) in free_cells:
                cells.append((r, c-1))
            if c < n-1 and (r, c+1) in free_cells:
                cells.append((r, c+1))

            if len(cells) == 5:
                placements.append(tuple(sorted(cells)))

    # If the number of free cells is not divisible by 5, impossible
    if len(free_cells) % 5 != 0:
        print("NO")
        return

    # Backtracking solver
    # We need to cover all free_cells.
    # Strategy: Find the first free cell (in sorted order) that is not yet covered.
    # Try all placements that cover this specific cell.
    # Mark those cells as covered and recurse.

    # To optimize, we can map each free cell to the list of placement indices that cover it.
    cell_to_placements = {cell: [] for cell in free_cells}
    for i, p in enumerate(placements):
        for cell in p:
            cell_to_placements[cell].append(i)

    # We will maintain a set of covered cells.
    # However, passing sets around is slow. Let's use a boolean grid for O(1) checks.
    # But since we need to backtrack, we need to restore the grid.

    covered_grid = [[False] * n for _ in range(n)]

    def get_first_uncovered():
        for r in range(n):
            for c in range(n):
                if (r, c) in free_cells and not covered_grid[r][c]:
                    return (r, c)
        return None

    def backtrack():
        target = get_first_uncovered()
        if target is None:
            return True

        r, c = target

        # Try all placements that cover (r, c)
        for p_idx in cell_to_placements[(r, c)]:
            p = placements[p_idx]

            # Check if this placement overlaps with any already covered cell
            valid = True
            for cell in p:
                if covered_grid[cell[0]][cell[1]]:
                    valid = False
                    break

            if valid:
                # Apply placement
                for cell in p:
                    covered_grid[cell[0]][cell[1]] = True

                if backtrack():
                    return True

                # Backtrack
                for cell in p:
                    covered_grid[cell[0]][cell[1]] = False

        return False

    if backtrack():
        print("YES")
    else:
        print("NO")

