        for r in range(n):
            for c in range(n):
                if grid[r][c] == '.':
                    cnt += 1
        return cnt

    def backtrack():
        pos = find_first_free()
        if pos is None:
            return True  # All cells filled

        r, c = pos

        # Optimization: If remaining free cells are not divisible by 5, fail immediately
        if count_free() % 5 != 0:
            return False

        # Try all possible centers that would cover (r, c)
        # A plus shape covering (r, c) can have its center at:
        # 1. (r, c) -> covers (r,c), (r-1,c), (r+1,c), (r,c-1), (r,c+1)
        # 2. (r+1, c) -> covers (r+1,c), (r,c), (r+2,c), (r+1,c-1), (r+1,c+1)
        # 3. (r-1, c) -> covers (r-1,c), (r-2,c), (r,c), (r-1,c-1), (r-1,c+1)
        # 4. (r, c+1) -> covers (r,c+1), (r-1,c+1), (r+1,c+1), (r,c), (r,c+2)
        # 5. (r, c-1) -> covers (r,c-1), (r-1,c-1), (r+1,c-1), (r,c), (r,c-2)

        candidates = [
            (r, c),
            (r + 1, c),
            (r - 1, c),
            (r, c + 1),
            (r, c - 1)
        ]

        for cr, cc in candidates:
            if can_place(cr, cc):
                place_piece(cr, cc)
                if backtrack():
                    return True
                remove_piece(cr, cc)

        return False

    if backtrack():
        print("YES")
    else:
        print("NO")

